SET search_path TO trustledger, public;
-- Embeddings are generated by the Next.js server using all-MiniLM-L6-v2 (384 dimensions).
-- Example vector similarity query. Replace the zero vector with a real 384-value embedding.
-- Lower cosine distance means higher similarity; <=> is pgvector cosine distance.
-- SELECT fact_id, fact_text, 1 - (embedding <=> '[...]'::vector) AS cosine_similarity
-- FROM memory_fact WHERE embedding IS NOT NULL
-- ORDER BY embedding <=> '[...]'::vector LIMIT 5;

-- Inspect vector readiness and embedding coverage.
SELECT COUNT(*) AS total_facts,
       COUNT(embedding) AS facts_with_embeddings,
       COUNT(*) FILTER (WHERE embedding IS NULL) AS facts_without_embeddings
FROM memory_fact;
